// When the battle scene exists and g_SuperNova_ResourceHandle is zero, destroys its seffect render
// objects, calls BattleStage_FreePartMesh for entries 6/7 and builds weapon/s_nova. Creates
// resource 0x38 with g_SuperNova_ResourceTable metadata, type-zero/default-duration options and
// scene context 0x4C, then loads the eleven retained sound IDs into buffer zero. Otherwise does
// nothing. Destruction precedes resource creation.
// FUNCTION: FF7 0x00439a00
void __cdecl BattleFx_WeaponLoadResSuperNova(void)
{
    GfxModelTableBank *sceneContext;
    GfxResourceRequest requestStorage;
    int kind;
    int pathBuffer[50];
    GfxResourceRequest *pRequest;
    int resourceTable;

    if (g_pBattle3dScene != 0 && g_SuperNova_ResourceHandle == 0) {
        Battle3d_DestroySeffectRenderObjects(((int)g_pBattle3dScene));
        BattleStage_FreePartMesh(6, g_pBattle3dScene->stageId);
        BattleStage_FreePartMesh(7, g_pBattle3dScene->stageId);
        kind = 0x38;
        resourceTable = (int)&g_SuperNova_ResourceTable;
        sceneContext = (GfxModelTableBank *)(g_pBattle3dScene->modelTableBank);
        pRequest = &requestStorage;
        Gfx_InitResourceRequest(pRequest);
        pRequest->groupTag = 0;
        // STRING: FF7 0x007d7df0
        pRequest->resourcePath = BattleFx_BuildResourcePath("weapon/s_nova", (char *)(pathBuffer));
        Gfx_LoadModelTableIfAbsent(kind, resourceTable, pRequest, &g_SuperNova_ResourceHandle, sceneContext);
        SfxLoadIntoBuffer(SFX_ID_LASBOSS_WING, 0);
        SfxLoadIntoBuffer(SFX_ID_LASBOSS_RUMBLE, 0);
        SfxLoadIntoBuffer(SFX_ID_LASBOSS_BEAM, 0);
        SfxLoadIntoBuffer(SFX_ID_EXPLOSION_IMPACT, 0);
        SfxLoadIntoBuffer(0xA3, 0);
        SfxLoadIntoBuffer(SFX_ID_SEPHIROTH_HUM, 0);
        SfxLoadIntoBuffer(SFX_ID_LASBOSS_SHATTER, 0);
        SfxLoadIntoBuffer(SFX_ID_LASBOSS_SHOCK, 0);
        SfxLoadIntoBuffer(SFX_ID_LASBOSS_FLARE, 0);
        SfxLoadIntoBuffer(SFX_ID_GARYOTEN_WIND, 0);
        SfxLoadIntoBuffer(SFX_ID_LASBOSS_FINALE, 0);
    }
}

