    RotMatrix(&g_SuperNova_InitStateTaskHandle, &g_SuperNova_CameraEasingState.easedValue);
    g_SuperNova_CameraEasingState.transZ = 0;
    g_SuperNova_CameraEasingState.transY = g_SuperNova_CameraEasingState.transZ;
    g_SuperNova_CameraEasingState.transX = g_SuperNova_CameraEasingState.transY;
    BattleFx_WeaponLoadResSuperNova();
    g_SuperNova_AllocatedHeapBuffer = BattleFx_SuperNovaLoadStage57Dat();
    g_SuperNova_RenderStateBlock = (struct BattleFxSuperNovaPointPrim *)(Gfx_GetPsxPacketScratchPtr());
