// Fetches the next operand from a bytecode stream: reads the short at the pointer stored at *pScriptPtr,
// advances that stored pointer by 2, and if the value is negative uses its negation minus one as
// an index into g_SuperNova_CameraScriptOperands, returning that entry instead. A non-negative value is
// returned as an immediate.
// FUNCTION: FF7 0x0043ae02
short __cdecl BattleFx_SuperNovaReadCameraScriptOperand(void *pScriptPtr)
{
    int val;

    val = *(short *)((char *)*(int *)pScriptPtr);
    *(int *)pScriptPtr += 2;
    if (val < 0) {
        val = g_SuperNova_CameraScriptOperands[-val - 1];
    }
    return (short)val;
}

// Repeatedly applies SinFixed(value divided by four) for the magnitude of easingParam shifted eight,
// using complemented input/output when easingParam is nonpositive; blends the transformed and original
// value using weight (easingParam low byte plus one) and returns the eight-bit-shifted result.
// FUNCTION: FF7 0x0043ae3c
int __cdecl BattleFx_SuperNovaApplyCameraEasing(int value, int easingParam)
{
    int iteration;
    int origValue;
    int passCount;

    origValue = value;
    if (easingParam > 0) {
        passCount = easingParam >> 8;
        for (iteration = 0; iteration < passCount; iteration++) {
            value = SinFixed(value / 4);
        }
    } else {
        easingParam = -easingParam;
        passCount = easingParam >> 8;
        value = 0x1000 - value;
        for (iteration = 0; iteration < passCount; iteration++) {
            value = SinFixed(value / 4);
        }
        value = 0x1000 - value;
    }
    passCount = (easingParam & 0xFF) + 1;
    value = value * passCount + origValue * (0x100 - passCount) >> 8;
    return value;
}
