// On main-slot counter zero clears the retained selection flags and two position arrays for
// g_SuperNova_TriangleRankingCount entries, then increments the counter. Later processes up to 64 output ranks per
// invocation, searching every unselected candidate for the minimum unsigned squared distance from
// the task position. Candidate point calculation averages its indexed vertex with two triples
// already present in the data-block scratch; this function does not initialize those scratch
// triples. Stores each chosen index and marks it selected, advancing the task counter afterwards.
// When output progress reaches the entry count clears all selection flags and retires.
// Data/vertex/rank extents are unchecked, signed short progress can wrap and r has no
// initialization when a search has no candidate.
// FUNCTION: FF7 0x0043d17e
void __cdecl BattleFx_SuperNovaRankTrianglesByDistanceTask(void)
{
    BattleFxIce3MultiTexturedShard *pCentroid;
    int blockBase;
    Vec3sPacked *vertC;
    BattleFxSuperNovaCameraDelta *deltaPtr;
    int stackWords; /* Unreferenced stack padding preserved for VC5 /Od frame size (see lib/codegen.h). */
    int indexTable;
    short candidate;
    short outRank;
    short batchEnd;
    int minDist;
    short firstRank;
    Vec3sPacked *scratchA;
    Vec3sPacked *pScratchB;
    short bestIndex;
    int squaredDist;
    SuperNovaRankTriangle *task;

    task = (SuperNovaRankTriangle *)BATTLE_CURRENT_TASK_SLOT;
    if (task->frameCount == 0) {
        for (outRank = 0; outRank < g_SuperNova_TriangleRankingCount; outRank++) {
            g_SuperNova_ActiveTriangleBufferPtr[outRank] = 0;
            g_SuperNova_TriangleRecordsBuffer[outRank].deltaZ = 0;
            g_SuperNova_TriangleRecordsBuffer[outRank].deltaY = 0;
            g_SuperNova_TriangleRecordsBuffer[outRank].deltaX = 0;
            g_SuperNova_ActiveMeshIndicesPtr[outRank].dispZ = 0;
            g_SuperNova_ActiveMeshIndicesPtr[outRank].dispY = 0;
            g_SuperNova_ActiveMeshIndicesPtr[outRank].dispX = 0;
        }
        (task->frameCount)++;
    } else {
        scratchA = (Vec3sPacked *)Gfx_GetPsxScratchpadPtr(0);
        pScratchB = (Vec3sPacked *)((int)scratchA + 8);
        vertC = (Vec3sPacked *)((int)pScratchB + 8);
        pCentroid = (BattleFxIce3MultiTexturedShard *)((int)vertC + 8);
        deltaPtr = (BattleFxSuperNovaCameraDelta *)((int)pCentroid + 8);
        blockBase = g_SuperNova_TriangleRankingSourcePtr + 4;
        indexTable = blockBase + *(int *)g_SuperNova_TriangleRankingSourcePtr;
        indexTable += 4;
        firstRank = task->frameCount - 1 << 6;
        batchEnd = firstRank + 0x40;
        if (batchEnd > g_SuperNova_TriangleRankingCount) {
            batchEnd = g_SuperNova_TriangleRankingCount;
        }
        for (outRank = firstRank; outRank < batchEnd; outRank++) {
            minDist = 0xFFFFFFFF;
            for (candidate = 0; candidate < g_SuperNova_TriangleRankingCount; candidate++) {
                if (g_SuperNova_ActiveTriangleBufferPtr[candidate] == 0) {
                    scratchA = (Vec3sPacked *)(blockBase + *(short *)((char *)indexTable + (candidate << 3) * 2));
                    pCentroid->centroidX = (scratchA->vx + pScratchB->vx + vertC->vx) / 3;
                    pCentroid->centroidY = (scratchA->vy + pScratchB->vy + vertC->vy) / 3;
                    pCentroid->centroidZ = (scratchA->vz + pScratchB->vz + vertC->vz) / 3;
                    deltaPtr->deltaX = pCentroid->centroidX - task->centerX;
                    deltaPtr->deltaY = pCentroid->centroidY - task->centerY;
                    deltaPtr->deltaZ = pCentroid->centroidZ - task->centerZ;
                    squaredDist = deltaPtr->deltaX * deltaPtr->deltaX + deltaPtr->deltaY * deltaPtr->deltaY + deltaPtr->deltaZ * deltaPtr->deltaZ;
                    if ((unsigned int)squaredDist < (unsigned int)minDist) {
                        minDist = squaredDist;
                        bestIndex = candidate;
                    }
                }
            }
            g_SuperNova_ActiveTriangleSubBufferPtr[outRank] = bestIndex;
            g_SuperNova_ActiveTriangleBufferPtr[bestIndex] = 1;
        }
        (task->frameCount)++;
        if (outRank == g_SuperNova_TriangleRankingCount) {
            for (outRank = 0; outRank < g_SuperNova_TriangleRankingCount; outRank++) {
                g_SuperNova_ActiveTriangleBufferPtr[outRank] = 0;
            }
            task->ownerSlot = BATTLE_TASK_FREE;
        }
    }
}

