// Returns while paused; otherwise emits BattleFx_SuperNovaDampedParticleModelTask on even main-slot
// counters. Before count 140 uses X -3000 through 2999, Y zero, Z -1000 through 2999, zero X/Z
// velocity, negative Y velocity -500 through -1999, scale 0x800 through 0x3FFF, random model index
// zero through two and duration twenty. At and after 140 sets global damping
// g_SuperNova_ParticleVelocityDampingQ12 to 0xF00 and uses X -5000 through 4999, Y -500 through -1,
// Z -2000 through -1, Y velocity -50 through -249, positive Z velocity 381 through 780 and scale
// 0x400 through 0x2FFF. Increments the emitter counter and retires only at exactly 220; disabled
// constant branches do not consume randomness.
// FUNCTION: FF7 0x0043e028
void __cdecl BattleFx_SuperNovaDampedParticleModelEmitterTask(void)
{
    BattleTaskSlot *taskPtr;
    short zRoll;
    int scaleValue;
    BattleFxSuperNovaDampedParticle *particle;
    int height;

    taskPtr = BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    if (taskPtr->frameCounter < 140) {
        if ((taskPtr->frameCounter % 2) == 0) {
            particle = (BattleFxSuperNovaDampedParticle *)BATTLE_NEW_TASK_SLOT(BattleFx_SuperNovaDampedParticleModelTask);
            zRoll = rand() % 0xFA0;
            particle->posX = rand() % 6000 - 3000;
            particle->posY = 0;
            particle->posZ = zRoll - 1000;
            particle->velocityX = 0;
            particle->velocityY = 0xFFFFFE0C - rand() % 1500;
            particle->velocityZ = 0;
            if (DEAD_IN_RETAIL != 0) {
                scaleValue = 0x4000 /* 4.0 */;
            } else {
                scaleValue = rand() % 0x3800 + 0x800;
            }
            particle->scale = scaleValue;
            particle->gravity = 0;
            particle->resourceIndex = rand() % 3;
            particle->duration = 20;
        }
    } else {
        g_SuperNova_ParticleVelocityDampingQ12 = 0xF00;
        if ((taskPtr->frameCounter % 2) == 0) {
            particle = (BattleFxSuperNovaDampedParticle *)BATTLE_NEW_TASK_SLOT(BattleFx_SuperNovaDampedParticleModelTask);
            particle->posX = rand() % 10000 - 5000;
            if (DEAD_IN_RETAIL != 0) {
                height = 0;
            } else {
                height = rand() % 500 - 500;
            }
            particle->posY = height;
            particle->posZ = rand() % 2000 - 2000;
            particle->velocityX = 0;
            particle->velocityY = 0xFFFFFFCE - rand() % 200;
            particle->velocityZ = 780 - rand() % 400;
            particle->scale = rand() % 0x2C00 + 0x400;
            particle->gravity = 0;
            particle->resourceIndex = rand() % 3;
            particle->duration = 20;
        }
    }
    (taskPtr->frameCounter)++;
    if (taskPtr->frameCounter == 220) {
        taskPtr->ownerSlot = BATTLE_TASK_FREE;
    }
}

